package com.ptc.halo;
import com.ptc.halo.entity.*;import com.ptc.halo.enums.*;import com.ptc.halo.repository.*;import com.ptc.halo.service.*;import com.ptc.halo.dtoRequest.AdminActingSessionRequest;
import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.orm.jpa.DataJpaTest;import org.springframework.context.annotation.Import;import org.springframework.transaction.support.TransactionTemplate;import static org.junit.jupiter.api.Assertions.*;
@DataJpaTest(properties="spring.jpa.properties.hibernate.dialect=org.hibernate.dialect.H2Dialect",showSql=false)
@Import({AdminActingSessionService.class,SuperAdminAdminModeService.class,ActivityLogService.class,AdminService.class,AdminProfessorPreviewService.class})
class SuperAdminModeTest {
 @org.springframework.boot.test.mock.mockito.MockBean org.springframework.security.crypto.password.PasswordEncoder encoder;
 @Autowired AdminService accounts;
 @Autowired AdminActingSessionService sessions;@Autowired SuperAdminAdminModeService mode;@Autowired UserRepository users;@Autowired StudentProfileRepository profiles;@Autowired AdminActingSessionRepository records;@Autowired ActivityLogRepository logs;@Autowired ActivityLogService audit;@Autowired org.springframework.transaction.PlatformTransactionManager manager;
 @Autowired AdminProfessorPreviewService professorPreview;
 @Autowired ProfessorRepository professorProfiles;
 UserEntity actor,admin,professor,student;
 @BeforeEach void setup(){actor=user(Role.SUPER_ADMIN);admin=user(Role.ADMIN);professor=user(Role.PROFESSOR);student=user(Role.STUDENT);var p=new StudentProfileEntity();p.setUser(student);p.setStudentId("TEST-"+student.getId());p.setSection("A");p.setYearLevel(YearLevel.FIRST_YEAR);profiles.saveAndFlush(p);}
 UserEntity user(Role role){var u=new UserEntity();u.setName("Synthetic");u.setEmail(java.util.UUID.randomUUID()+"@example.test");u.setRole(role);u.setStatus(Status.ACTIVE);return users.saveAndFlush(u);}
 String enter(UserEntity target){return sessions.create(TestIdentity.auth(actor),new AdminActingSessionRequest(target.getId(),target.getRole())).id();}
 void code(AdminApiException.Code code,org.junit.jupiter.api.function.Executable work){assertEquals(code,assertThrows(AdminApiException.class,work).code);}
 @Test void allThreeTargetsKeepOriginalIdentityAndExit(){for(var target:java.util.List.of(admin,professor,student)){String id=enter(target);var response=sessions.validate(TestIdentity.auth(actor),id);assertEquals(actor.getId(),response.adminUserId());assertEquals(target.getId(),response.target().userId());assertEquals(Role.SUPER_ADMIN,users.findById(actor.getId()).orElseThrow().getRole());sessions.revoke(TestIdentity.auth(actor),id);code(AdminApiException.Code.ACTING_SESSION_INVALID,()->sessions.validate(TestIdentity.auth(actor),id));}}
 @Test void adminModeRejectsNestedRealAndPreviewModes(){String id=enter(admin);code(AdminApiException.Code.ACTING_MODE_ALREADY_ACTIVE,()->enter(professor));code(AdminApiException.Code.ACTING_MODE_ALREADY_ACTIVE,()->sessions.createStudentPreview(TestIdentity.auth(actor),student.getId()));code(AdminApiException.Code.ACTING_MODE_ALREADY_ACTIVE,()->sessions.createProfessorPreview(TestIdentity.auth(actor),professor.getId()));assertEquals(1,records.count());sessions.revoke(TestIdentity.auth(actor),id);assertNotNull(enter(student));}
 @Test void previewCannotAuthorizeRealWritesOrStartAnotherMode(){var preview=sessions.createStudentPreview(TestIdentity.auth(actor),student.getId());code(AdminApiException.Code.RESOURCE_NOT_FOUND,()->new TransactionTemplate(manager).execute(tx->sessions.requireStudent(TestIdentity.auth(actor),preview.getId())));code(AdminApiException.Code.ACTING_MODE_ALREADY_ACTIVE,()->enter(admin));assertEquals(0,records.count());sessions.endStudentPreview(TestIdentity.auth(actor),preview);assertNotNull(enter(admin));}
 @Test void adminTargetAuditsOriginalActorAndCleansContext(){String id=enter(admin);mode.execute(TestIdentity.auth(actor),id,target->{assertEquals(admin.getId(),target.getId());audit.createLog(target,ActivityType.ACCOUNT,"Synthetic Admin action");return null;});var log=logs.findAll().stream().filter(l->l.getAction().contains("Synthetic Admin action")).findFirst().orElseThrow();assertEquals(actor.getId(),log.getUser().getId());assertEquals(admin.getId(),log.getActingTarget().getId());assertEquals(id,log.getActingSession().getId());audit.createLog(admin,ActivityType.ACCOUNT,"Normal Admin action");assertNull(logs.findAll().stream().filter(l->l.getAction().equals("Normal Admin action")).findFirst().orElseThrow().getActingSession());}
 @Test void wrongOwnerAndWrongTargetFailClosed(){String id=enter(professor);code(AdminApiException.Code.INVALID_TARGET_ROLE,()->mode.execute(TestIdentity.auth(actor),id,t->null));var stranger=user(Role.SUPER_ADMIN);code(AdminApiException.Code.RESOURCE_NOT_FOUND,()->sessions.validate(TestIdentity.auth(stranger),id));assertThrows(org.springframework.security.access.AccessDeniedException.class,()->mode.execute(TestIdentity.auth(admin),id,t->null));}
 @Test void regularAdminCannotTargetAdminsOrSuperAdmins(){for(var target:java.util.List.of(admin,actor))code(AdminApiException.Code.INVALID_TARGET_ROLE,()->sessions.create(TestIdentity.auth(admin),new AdminActingSessionRequest(target.getId(),target.getRole())));assertNotNull(sessions.create(TestIdentity.auth(admin),new AdminActingSessionRequest(professor.getId(),Role.PROFESSOR)));assertNotNull(sessions.create(TestIdentity.auth(admin),new AdminActingSessionRequest(student.getId(),Role.STUDENT)));}
 @Test void expiredRevokedAndLogoutVersionFailClosed(){String id=enter(admin);actor.setTokenVersion(actor.getTokenVersion()+1);users.saveAndFlush(actor);code(AdminApiException.Code.ACTING_SESSION_INVALID,()->mode.execute(TestIdentity.auth(actor),id,t->null));assertNotNull(enter(student));}
 @Test void inactiveTargetsWrongRolesAndMissingProfilesAreRejected(){admin.setStatus(Status.INACTIVE);users.saveAndFlush(admin);code(AdminApiException.Code.ACTING_TARGET_INACTIVE,()->enter(admin));code(AdminApiException.Code.INVALID_TARGET_ROLE,()->sessions.create(TestIdentity.auth(actor),new AdminActingSessionRequest(professor.getId(),Role.ADMIN)));profiles.deleteAll();code(AdminApiException.Code.PROFILE_INCOMPLETE,()->enter(student));}

 @Test void delegatedAccountMutationUsesTargetPermissionsAndOriginalAuditIdentity(){String id=enter(admin);mode.execute(TestIdentity.auth(actor),id,target->accounts.changeStudentStatus(student.getId(),Status.INACTIVE,target));assertEquals(Status.INACTIVE,users.findById(student.getId()).orElseThrow().getStatus());assertEquals(Role.SUPER_ADMIN,users.findById(actor.getId()).orElseThrow().getRole());var actions=logs.findAll().stream().filter(l->l.getActingSession()!=null&&l.getActingSession().getId().equals(id)).toList();assertTrue(actions.size()>=2);assertTrue(actions.stream().allMatch(l->l.getUser().getId().equals(actor.getId())&&l.getActingTarget().getId().equals(admin.getId())));}
 @Test void expiredSessionCannotExecuteAdminOperation(){var now=java.time.Instant.now();var expired=records.saveAndFlush(new AdminActingSessionEntity(java.util.UUID.randomUUID().toString(),actor,admin,now.minusSeconds(3600),now.minusSeconds(1)));code(AdminApiException.Code.ACTING_SESSION_INVALID,()->mode.execute(TestIdentity.auth(actor),expired.getId(),t->null));assertNotNull(enter(admin));}

 @Test @org.springframework.transaction.annotation.Transactional(propagation=org.springframework.transaction.annotation.Propagation.NOT_SUPPORTED)
 @org.springframework.test.annotation.DirtiesContext(methodMode=org.springframework.test.annotation.DirtiesContext.MethodMode.AFTER_METHOD)
 void professorPreviewSurvivesSeparateRequestTransactions(){
  var p=new ProfessorEntity();p.setUser(professor);p.setProfessorId("SYN-"+professor.getId());professorProfiles.saveAndFlush(p);
  var created=professorPreview.create(TestIdentity.auth(actor),professor.getId());
  assertEquals(professor.getId(),professorPreview.validate(TestIdentity.auth(actor),created.id()).target().userId());
  assertEquals(created.id(),sessions.activeModes(TestIdentity.auth(actor)).get(0).session().id());
  assertTrue(sessions.activeModes(TestIdentity.auth(actor)).get(0).preview());
  var stranger=user(Role.SUPER_ADMIN);
  assertTrue(sessions.activeModes(TestIdentity.auth(stranger)).isEmpty());
  code(AdminApiException.Code.RESOURCE_NOT_FOUND,()->sessions.exitActiveMode(TestIdentity.auth(stranger),created.id()));
  sessions.exitActiveMode(TestIdentity.auth(actor),created.id());
  code(AdminApiException.Code.ACTING_SESSION_INVALID,()->professorPreview.validate(TestIdentity.auth(actor),created.id()));
  assertTrue(sessions.activeModes(TestIdentity.auth(actor)).isEmpty());
  assertNotNull(enter(admin));
 }
 @Test void activeDiscoveryPreservesOwnershipAndDoesNotCreateModes(){String id=enter(admin);var modes=sessions.activeModes(TestIdentity.auth(actor));assertEquals(1,modes.size());assertFalse(modes.get(0).preview());assertEquals(id,modes.get(0).session().id());assertThrows(org.springframework.security.access.AccessDeniedException.class,()->sessions.activeModes(TestIdentity.auth(admin)));sessions.exitActiveMode(TestIdentity.auth(actor),id);assertTrue(sessions.activeModes(TestIdentity.auth(actor)).isEmpty());assertNotNull(enter(professor));}
 @Test void invalidatedPreviewDoesNotStrandActorInAnUnusableMode(){var preview=sessions.createStudentPreview(TestIdentity.auth(actor),student.getId());student.setTokenVersion(student.getTokenVersion()+1);users.saveAndFlush(student);code(AdminApiException.Code.ACTING_SESSION_INVALID,()->sessions.validateStudentPreview(TestIdentity.auth(actor),preview));assertNotNull(enter(admin));}
}
